const tenancies = H.lane('tenancies')
  .of(tenancy)
  .from(
    supply.manual<TenancyData>().key(d => d.tenant),
    supply.schedule<TenancyData>({
      cron: '0 9 1 * *',
      units: (_now, _ctx, known) => known.filter(u => u.state === customer).map(u => u.data),
    }).key(d => d.tenant).updatesOnly(),
