  .of(backup)
  .from(supply.schedule({ cron: '0 1 * * *', units: () => databases }).key(b => b.database))
  .handle(backupFlow)
  .exits({ backedUp, failed: { tries: 1, backoff: 'none', then: backupFailed } })
  .facet(serviceFacet, b => b.database);

