    H.ops.work.write,
    H.ops.resolve(approval),
    H.ops.resolve(budget),
    H.ops.resolve(escalationHandled),
    H.ops.resolve(auditReview),
    H.ops.memory.write(tasteJournal),
    H.ops.memory.curate(tasteJournal, experienceJournal),
    H.ops.telemetry.read,
