  .input(z.object({ title: z.string(), counterparty: z.string(), redlines: z.array(z.string()) }))
  .output(z.object({ document: z.string() }));
const drafter = H.seat('contract-drafter').role(drafterRole).skill(draftSkill).models(opus);

