    .supply(H.operator)
    .store(documents)
    .handler(contractFlow, {
      exits: { declined: Declined, rejected: SignoffRejected, executed: Executed },
      during: { draft: Drafting, execute: Executing, counsel: WithCounsel, signoff: AwaitingSignoff },
