  .step('probe', probeService, state => ({ service: state.input.service }))
  .when(state => state.probe.healthy, ok => ok.exit('healthy'))
  .exit('unhealthy');

const nightlyBackup = H.flow('nightly-backup')
  .input(backupTarget)
  .step('dump', backupDatabase, state => state.input)
