      on: H.events.transitions(incidents),
      text: event => `Incident ${event.unit.key} "${event.unit.data.title}": ${event.from ?? 'created'} → ${event.to}`,
    }),
    observers.board({ path: 'BOARD.md' }),
  );

export default harness;

