const drafterSeat = H.seat('drafter-seat').role(drafter).skill(draftReply).models(sonnet);

const helpdeskRunner = runners.local({ name: 'helpdesk-runner', slots: 4 }).env({ HELPDESK_TOKEN: H.env('HELPDESK_TOKEN') });

